CREATE TABLE "ConsolidacionesCarga" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Codigo" character varying(20) NOT NULL,
    "Nombre" character varying(100) NOT NULL,
    "Estado" character varying(15) NOT NULL DEFAULT 'Borrador',
    "Observaciones" character varying(500),
    "FechaConfirmacion" timestamptz,
    "MotivoCancelacion" character varying(500),
    "FechaCancelacion" timestamptz,
    CONSTRAINT "PK_ConsolidacionesCarga" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_ConsolidacionesCarga_Textos" CHECK (length(btrim("Codigo")) > 0 AND length(btrim("Nombre")) > 0),
    CONSTRAINT "CK_ConsolidacionesCarga_Estado" CHECK (
        ("Estado" = 'Borrador' AND "FechaConfirmacion" IS NULL AND "FechaCancelacion" IS NULL AND "MotivoCancelacion" IS NULL)
        OR ("Estado" = 'Confirmada' AND "FechaConfirmacion" IS NOT NULL AND "FechaCancelacion" IS NULL AND "MotivoCancelacion" IS NULL)
        OR ("Estado" = 'Cancelada' AND "FechaCancelacion" IS NOT NULL AND "MotivoCancelacion" IS NOT NULL AND length(btrim("MotivoCancelacion")) > 0))
);
CREATE UNIQUE INDEX "IX_ConsolidacionesCarga_CodigoNormalizado" ON "ConsolidacionesCarga" (lower(btrim("Codigo")));

CREATE TABLE "LineasConsolidacionCarga" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "ConsolidacionCargaId" integer NOT NULL,
    "Posicion" integer NOT NULL,
    "Sku" character varying(40) NOT NULL,
    "Descripcion" character varying(200) NOT NULL,
    "Cantidad" integer NOT NULL,
    "CantidadRecogida" integer NOT NULL DEFAULT 0,
    "UnidadesPorBulto" integer NOT NULL DEFAULT 0,
    "LargoCm" numeric(6,2) NOT NULL DEFAULT 0,
    "AnchoCm" numeric(6,2) NOT NULL DEFAULT 0,
    "AltoCm" numeric(6,2) NOT NULL DEFAULT 0,
    "PesoBultoKg" numeric(8,2) NOT NULL DEFAULT 0,
    CONSTRAINT "PK_LineasConsolidacionCarga" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_LineasConsolidacionCarga_Consolidacion" FOREIGN KEY ("ConsolidacionCargaId") REFERENCES "ConsolidacionesCarga" ("Id") ON DELETE CASCADE,
    CONSTRAINT "CK_LineasConsolidacionCarga_Textos" CHECK (length(btrim("Sku")) > 0 AND length(btrim("Descripcion")) > 0),
    CONSTRAINT "CK_LineasConsolidacionCarga_Cantidades" CHECK ("Posicion" BETWEEN 1 AND 100 AND "Cantidad" BETWEEN 1 AND 1000000 AND "CantidadRecogida" BETWEEN 0 AND "Cantidad" AND "UnidadesPorBulto" BETWEEN 0 AND 1000000),
    CONSTRAINT "CK_LineasConsolidacionCarga_Packing" CHECK ("LargoCm" >= 0 AND "AnchoCm" >= 0 AND "AltoCm" >= 0 AND "PesoBultoKg" >= 0)
);
CREATE INDEX "IX_LineasConsolidacionCarga_ConsolidacionCargaId" ON "LineasConsolidacionCarga" ("ConsolidacionCargaId");
